00035     public function __construct($args)
00036     {
00037         global $bearsamppRoot, $bearsamppCore, $bearsamppLang, $bearsamppBins, $bearsamppWinbinder;
00038         $this->writeLog( 'Starting ' . APP_TITLE );
00039 
00040         // Admin check is now performed in root.php before ActionStartup is instantiated
00041         // This prevents screen flashes and ensures the check happens before any WinBinder initialization
00042         Log::info('Administrator privileges confirmed - proceeding with startup');
00043 
00044         // Init
00045         $this->splash    = new Splash();
00046         $this->restart   = false;
00047         $this->startTime = Util::getMicrotime();
00048         $this->error     = '';
00049 
00050         $this->rootPath    = Path::getRootPath();
00051         $this->filesToScan = array();
00052 
00053         $gauge = self::GAUGE_SERVICES * count( $bearsamppBins->getServices() );
00054         $gauge += self::GAUGE_OTHERS + 1;
00055 
00056         // Start splash screen
00057         $this->splash->init(
00058             $bearsamppLang->getValue( Lang::STARTUP ),
00059             $gauge,
00060             sprintf( $bearsamppLang->getValue( Lang::STARTUP_STARTING_TEXT ), APP_TITLE . ' ' . $bearsamppCore->getAppVersion() )
00061         );
00062 
00063         $bearsamppWinbinder->setHandler( $this->splash->getWbWindow(), $this, 'processWindow', 1000 );
00064         $bearsamppWinbinder->mainLoop();
00065         $bearsamppWinbinder->reset();
00066     }
