00077     public function processWindow($window, $id, $ctrl, $param1, $param2)
00078     {
00079         global $bearsamppRoot, $bearsamppCore, $bearsamppLang, $bearsamppBins, $bearsamppTools, $bearsamppApps, $bearsamppWinbinder;
00080 
00081         Log::trace('Starting processWindow method');
00082 
00083         // Admin check is now performed in the constructor before anything else
00084         // No need to check again here
00085 
00086         // Rotation logs
00087         Log::trace('Performing log rotation');
00088         $this->rotationLogs();
00089 
00090         // Clean
00091         Log::trace('Starting cleanup operations');
00092         $this->cleanTmpFolders();
00093         $this->cleanOldBehaviors();
00094 
00095         // List procs
00096         Log::trace('Listing running processes');
00097         if ($bearsamppRoot->getProcs() !== false) {
00098             $this->writeLog('List procs:');
00099             $listProcs = array();
00100             foreach ($bearsamppRoot->getProcs() as $proc) {
00101                 $unixExePath = Path::formatUnixPath($proc[Win32Ps::EXECUTABLE_PATH]);
00102                 $listProcs[] = '-> ' . basename($unixExePath) . ' (PID ' . $proc[Win32Ps::PROCESS_ID] . ') in ' . $unixExePath;
00103             }
00104             sort($listProcs);
00105             foreach ($listProcs as $proc) {
00106                 $this->writeLog($proc);
00107             }
00108             Log::trace('Found ' . count($listProcs) . ' running processes');
00109         } else {
00110             Log::trace('No processes found or unable to retrieve process list');
00111         }
00112 
00113         // List modules
00114         Log::trace('Listing bins modules');
00115         $this->writeLog('List bins modules:');
00116         foreach ($bearsamppBins->getAll() as $module) {
00117             if (!$module->isEnable()) {
00118                 $this->writeLog('-> ' . $module->getName() . ': ' . $bearsamppLang->getValue(Lang::DISABLED));
00119                 Log::trace('Bin module ' . $module->getName() . ' is disabled');
00120             } else {
00121                 $this->writeLog('-> ' . $module->getName() . ': ' . $module->getVersion() . ' (' . $module->getRelease() . ')');
00122                 Log::trace('Bin module ' . $module->getName() . ': ' . $module->getVersion() . ' (' . $module->getRelease() . ')');
00123             }
00124         }
00125 
00126         Log::trace('Listing tools modules');
00127         $this->writeLog('List tools modules:');
00128         foreach ($bearsamppTools->getAll() as $module) {
00129             if (!$module->isEnable()) {
00130                 $this->writeLog('-> ' . $module->getName() . ': ' . $bearsamppLang->getValue(Lang::DISABLED));
00131                 Log::trace('Tool module ' . $module->getName() . ' is disabled');
00132             } else {
00133                 $this->writeLog('-> ' . $module->getName() . ': ' . $module->getVersion() . ' (' . $module->getRelease() . ')');
00134                 Log::trace('Tool module ' . $module->getName() . ': ' . $module->getVersion() . ' (' . $module->getRelease() . ')');
00135             }
00136         }
00137 
00138         Log::trace('Listing apps modules');
00139         $this->writeLog('List apps modules:');
00140         foreach ($bearsamppApps->getAll() as $module) {
00141             if (!$module->isEnable()) {
00142                 $this->writeLog('-> ' . $module->getName() . ': ' . $bearsamppLang->getValue(Lang::DISABLED));
00143                 Log::trace('App module ' . $module->getName() . ' is disabled');
00144             } else {
00145                 $this->writeLog('-> ' . $module->getName() . ': ' . $module->getVersion() . ' (' . $module->getRelease() . ')');
00146                 Log::trace('App module ' . $module->getName() . ': ' . $module->getVersion() . ' (' . $module->getRelease() . ')');
00147             }
00148         }
00149 
00150         // Kill old instances
00151         Log::trace('Killing old instances');
00152         $this->killOldInstances();
00153 
00154         // Prepare app
00155         Log::trace('Preparing application - refreshing hostname');
00156         $this->refreshHostname();
00157 
00158         Log::trace('Checking launch startup settings');
00159         $this->checkLaunchStartup();
00160 
00161         Log::trace('Checking browser configuration');
00162         $this->checkBrowser();
00163 
00164         Log::trace('Gathering system information');
00165         $this->sysInfos();
00166 
00167         Log::trace('Refreshing aliases');
00168         $this->refreshAliases();
00169 
00170         Log::trace('Refreshing virtual hosts');
00171         $this->refreshVhosts();
00172 
00173         // Check app path
00174         Log::trace('Checking application path');
00175         $this->checkPath();
00176 
00177         Log::trace('Scanning folders');
00178         $this->scanFolders();
00179 
00180         Log::trace('Changing paths in files');
00181         $this->changePath();
00182 
00183         Log::trace('Saving current path');
00184         $this->savePath();
00185 
00186         // Check BEARSAMPP_PATH, BEARSAMPP_BINS and System Path reg keys
00187         Log::trace('Checking PATH registry key');
00188         $this->checkPathRegKey();
00189 
00190         Log::trace('Checking BINS registry key');
00191         $this->checkBinsRegKey();
00192 
00193         Log::trace('Checking System PATH registry key');
00194         $this->checkSystemPathRegKey();
00195 
00196         // Update config
00197         Log::trace('Updating configuration');
00198         $this->updateConfig();
00199 
00200         // Create SSL certificates
00201         Log::trace('Creating SSL certificates');
00202         $this->createSslCrts();
00203 
00204         // Install
00205         Log::trace('Installing services');
00206         $this->installServices();
00207 
00208         // Actions if everything OK
00209         if (!$this->restart && empty($this->error)) {
00210             Log::trace('Startup completed successfully - refreshing Git repositories');
00211             $this->refreshGitRepos();
00212             $startupTime = round(Util::getMicrotime() - $this->startTime, 3);
00213             $this->writeLog('Started in ' . $startupTime . 's');
00214             Log::trace('Application started successfully in ' . $startupTime . ' seconds');
00215 
00216             // Log total startup time in VERBOSE_TRACE mode (mode 3)
00217             global $bearsamppConfig;
00218             if ($bearsamppConfig->getLogsVerbose() == Config::VERBOSE_TRACE) {
00219                 $minutes = floor($startupTime / 60);  // floor() returns int-compatible value
00220                 $seconds = fmod($startupTime, 60);
00221                 $formattedTime = sprintf('%d:%05.2f', $minutes, $seconds);
00222                 Log::trace('=== TOTAL STARTUP TIME: ' . $formattedTime . ' ===');
00223             }
00224         } else {
00225             Log::trace('Startup issues detected - incrementing progress bar');
00226             $this->splash->incrProgressBar(2);
00227         }
00228 
00229         if ($this->restart) {
00230             Log::trace('Restart required - preparing to restart application');
00231             $this->writeLog(APP_TITLE . ' has to be restarted');
00232             $this->splash->setTextLoading(
00233                 sprintf(
00234                     $bearsamppLang->getValue(Lang::STARTUP_PREPARE_RESTART_TEXT),
00235                     APP_TITLE . ' ' . $bearsamppCore->getAppVersion()
00236                 )
00237             );
00238 
00239             Log::trace('Deleting all services before restart');
00240             foreach ($bearsamppBins->getServices() as $sName => $service) {
00241                 Log::trace('Deleting service: ' . $sName);
00242                 $service->delete();
00243             }
00244 
00245             Log::trace('Setting execution action to RESTART');
00246             $bearsamppCore->setExec(ActionExec::RESTART);
00247         }
00248 
00249         if (!empty($this->error)) {
00250             Log::trace('Errors occurred during startup: ' . $this->error);
00251             $this->writeLog('Error: ' . $this->error);
00252             $bearsamppWinbinder->messageBoxError($this->error, $bearsamppLang->getValue(Lang::STARTUP_ERROR_TITLE));
00253         }
00254 
00255         Log::trace('Starting loading screen');
00256         // Moved Util::startLoading() to after splash window destruction to prevent double progress bars
00257 
00258         // Give the loading window time to initialize before we terminate this process
00259         Log::trace('Waiting for loading window to initialize');
00260         usleep(500000); // 500ms delay to allow loading window to start
00261 
00262         Log::trace('Loading process started');
00263 
00264         // Closing cli to finish startup
00265         Log::trace('Finishing startup process');
00266 
00267         // Safely reset WinBinder and destroy the splash window
00268         $bearsamppWinbinder->destroyWindow($window);
00269         $bearsamppWinbinder->reset();
00270 
00271         // Start loading screen AFTER splash window is destroyed to prevent double progress bars
00272         Util::startLoading();
00273 
00274         // Exit this startup process cleanly - the loading window will continue running
00275         Log::trace('Exiting startup process cleanly');
00276         exit(0);
00277 
00278     }
