00284     private function rotationLogs()
00285     {
00286         global $bearsamppRoot, $bearsamppCore, $bearsamppConfig, $bearsamppLang, $bearsamppBins;
00287 
00288         Log::trace("Starting log rotation process");
00289         $this->splash->setTextLoading($bearsamppLang->getValue(Lang::STARTUP_ROTATION_LOGS_TEXT));
00290         $this->splash->incrProgressBar();
00291 
00292         $archivesPath = Path::getLogsPath() . '/archives';
00293         if (!is_dir($archivesPath)) {
00294             Log::trace("Creating archives directory: " . $archivesPath);
00295             mkdir($archivesPath, 0777, true);
00296             return;
00297         }
00298 
00299         $date = date('Y-m-d-His', time());
00300         $archiveLogsPath = $archivesPath . '/' . $date;
00301         $archiveScriptsPath = $archiveLogsPath . '/scripts';
00302 
00303         // Create archive folders
00304         Log::trace("Creating archive directories for current rotation");
00305         if (!is_dir($archiveLogsPath)) {
00306             Log::trace("Creating logs archive directory: " . $archiveLogsPath);
00307             mkdir($archiveLogsPath, 0777, true);
00308         } else {
00309             Log::trace("Logs archive directory already exists: " . $archiveLogsPath);
00310         }
00311 
00312         if (!is_dir($archiveScriptsPath)) {
00313             Log::trace("Creating scripts archive directory: " . $archiveScriptsPath);
00314             mkdir($archiveScriptsPath, 0777, true);
00315         } else {
00316             Log::trace("Scripts archive directory already exists: " . $archiveScriptsPath);
00317         }
00318 
00319         // Count archives
00320         Log::trace("Counting existing archives");
00321         $archives = array();
00322         $handle = @opendir($archivesPath);
00323         if (!$handle) {
00324             Log::trace("Failed to open archives directory: " . $archivesPath);
00325             return;
00326         }
00327 
00328         while (false !== ($file = readdir($handle))) {
00329             if ($file == '.' || $file == '..') {
00330                 continue;
00331             }
00332             $archives[] = $archivesPath . '/' . $file;
00333         }
00334         closedir($handle);
00335         sort($archives);
00336         Log::trace("Found " . count($archives) . " existing archives");
00337 
00338         // Remove old archives
00339         if (count($archives) > $bearsamppConfig->getMaxLogsArchives()) {
00340             $total = count($archives) - $bearsamppConfig->getMaxLogsArchives();
00341             Log::trace("Removing " . $total . " old archives");
00342             for ($i = 0; $i < $total; $i++) {
00343                 Log::trace("Deleting old archive: " . $archives[$i]);
00344                 Util::deleteFolder($archives[$i]);
00345             }
00346         }
00347 
00348         // Helper function to check if a file is locked
00349         $isFileLocked = function($filePath) {
00350             if (!file_exists($filePath)) {
00351                 return false;
00352             }
00353 
00354             $handle = @fopen($filePath, 'r+');
00355             if ($handle === false) {
00356                 Log::trace("File appears to be locked: " . $filePath);
00357                 return true; // File is locked
00358             }
00359 
00360             fclose($handle);
00361             return false; // File is not locked
00362         };
00363 
00364         // Logs
00365         Log::trace("Archiving log files");
00366         $srcPath = Path::getLogsPath();
00367         $handle = @opendir($srcPath);
00368         if (!$handle) {
00369             Log::trace("Failed to open logs directory: " . $srcPath);
00370             return;
00371         }
00372 
00373         $logsCopied = 0;
00374         $logsSkipped = 0;
00375 
00376         while (false !== ($file = readdir($handle))) {
00377             if ($file == '.' || $file == '..' || is_dir($srcPath . '/' . $file)) {
00378                 continue;
00379             }
00380 
00381             $sourceFile = $srcPath . '/' . $file;
00382             $destFile = $archiveLogsPath . '/' . $file;
00383 
00384             // Check if file is locked before attempting to copy
00385             if ($isFileLocked($sourceFile)) {
00386                 Log::trace("Skipping locked log file: " . $file);
00387                 $logsSkipped++;
00388                 continue;
00389             }
00390 
00391             try {
00392                 if (copy($sourceFile, $destFile)) {
00393                     $logsCopied++;
00394                     Log::trace("Archived log file: " . $file);
00395                 } else {
00396                     $logsSkipped++;
00397                     Log::trace("Failed to copy log file: " . $file);
00398                 }
00399             } catch (Exception $e) {
00400                 $logsSkipped++;
00401                 Log::trace("Exception copying log file " . $file . ": " . $e->getMessage());
00402             }
00403         }
00404         closedir($handle);
00405         Log::trace("Logs archived: " . $logsCopied . " copied, " . $logsSkipped . " skipped");
00406 
00407         // Scripts
00408         Log::trace("Archiving script files");
00409         $srcPath = Path::getTmpPath();
00410         $handle = @opendir($srcPath);
00411         if (!$handle) {
00412             Log::trace("Failed to open tmp directory: " . $srcPath);
00413             return;
00414         }
00415 
00416         $scriptsCopied = 0;
00417         $scriptsSkipped = 0;
00418 
00419         while (false !== ($file = readdir($handle))) {
00420             if ($file == '.' || $file == '..' || is_dir($srcPath . '/' . $file)) {
00421                 continue;
00422             }
00423 
00424             $sourceFile = $srcPath . '/' . $file;
00425             $destFile = $archiveScriptsPath . '/' . $file;
00426 
00427             // Check if file is locked before attempting to copy
00428             if ($isFileLocked($sourceFile)) {
00429                 Log::trace("Skipping locked script file: " . $file);
00430                 $scriptsSkipped++;
00431                 continue;
00432             }
00433 
00434             try {
00435                 if (copy($sourceFile, $destFile)) {
00436                     $scriptsCopied++;
00437                     Log::trace("Archived script file: " . $file);
00438                 } else {
00439                     $scriptsSkipped++;
00440                     Log::trace("Failed to copy script file: " . $file);
00441                 }
00442             } catch (Exception $e) {
00443                 $scriptsSkipped++;
00444                 Log::trace("Exception copying script file " . $file . ": " . $e->getMessage());
00445             }
00446         }
00447         closedir($handle);
00448         Log::trace("Scripts archived: " . $scriptsCopied . " copied, " . $scriptsSkipped . " skipped");
00449 
00450         // Purge logs - only delete files that aren't locked
00451         Log::trace("Purging log files");
00452         $logsPath = Path::getLogsPath();
00453         $handle = @opendir($logsPath);
00454         if (!$handle) {
00455             Log::trace("Failed to open logs directory for purging: " . $logsPath);
00456             return;
00457         }
00458 
00459         $logsDeleted = 0;
00460         $logsPurgeSkipped = 0;
00461 
00462         while (false !== ($file = readdir($handle))) {
00463             if ($file == '.' || $file == '..' || $file == 'archives' || $file == '.gitignore' || is_dir($logsPath . '/' . $file)) {
00464                 continue;
00465             }
00466 
00467             $filePath = $logsPath . '/' . $file;
00468 
00469             // Check if file is locked before attempting to delete
00470             if ($isFileLocked($filePath)) {
00471                 Log::trace("Skipping locked log file during purge: " . $file);
00472                 $logsPurgeSkipped++;
00473                 continue;
00474             }
00475 
00476             try {
00477                 if (is_link($filePath)) {
00478                     if (@unlink($filePath)) {
00479                         $logsDeleted++;
00480                         Log::trace("Purged log symlink: " . $file);
00481                     } else {
00482                         $logsPurgeSkipped++;
00483                         Log::trace("Failed to purge log symlink: " . $file);
00484                     }
00485                 } elseif (file_exists($filePath)) {
00486                     if (@unlink($filePath)) {
00487                         $logsDeleted++;
00488                         Log::trace("Purged log file: " . $file);
00489                     } else {
00490                         $logsPurgeSkipped++;
00491                         Log::trace("Failed to purge log file: " . $file);
00492                     }
00493                 } else {
00494                     $logsPurgeSkipped++;
00495                     Log::trace("Log file already removed or does not exist: " . $file);
00496                 }
00497             } catch (Exception $e) {
00498                 $logsPurgeSkipped++;
00499                 Log::trace("Exception purging log file " . $file . ": " . $e->getMessage());
00500             }
00501         }
00502         closedir($handle);
00503         Log::trace("Logs purged: " . $logsDeleted . " deleted, " . $logsPurgeSkipped . " skipped");
00504 
00505         Log::trace("Log rotation completed");
00506     }
