00511     private function cleanTmpFolders()
00512     {
00513         global $bearsamppRoot, $bearsamppLang, $bearsamppCore;
00514 
00515         $this->splash->setTextLoading( $bearsamppLang->getValue( Lang::STARTUP_CLEAN_TMP_TEXT ) );
00516         $this->splash->incrProgressBar();
00517 
00518         $this->writeLog( 'Clear tmp folders' );
00519         Util::clearFolder( Path::getTmpPath(), array('cachegrind', 'composer', 'openssl', 'mailpit', 'xlight', 'npm-cache', 'pip', 'opcache', '.gitignore') );
00520         Util::clearFolder( Path::getTmpPath(), array('.gitignore') );
00521 
00522         // Ensure opcache directory exists for persistent file cache
00523         $opcachePath = Path::getTmpPath() . DIRECTORY_SEPARATOR . 'opcache';
00524 
00525         if (!is_dir($opcachePath)) {
00526             $this->writeLog('Creating opcache directory: ' . $opcachePath);
00527             if (!@mkdir($opcachePath, 0755, true) && !is_dir($opcachePath)) {
00528                 $this->writeLog('Failed to create opcache directory: ' . $opcachePath);
00529                 return;
00530             }
00531         }
00532 
00533         if (!is_writable($opcachePath)) {
00534             $this->writeLog('Opcache directory is not writable: ' . $opcachePath);
00535         }
00536     }
