00701     private function scanFolders()
00702     {
00703         global $bearsamppCore, $bearsamppLang;
00704 
00705         $this->splash->setTextLoading( $bearsamppLang->getValue( Lang::STARTUP_SCAN_FOLDERS_TEXT ) );
00706         $this->splash->incrProgressBar();
00707 
00708         $lastPath = $bearsamppCore->getLastPathContent();
00709         $currentPath = $this->rootPath;
00710 
00711         // Performance optimization: Skip scan if path hasn't changed
00712         // BUT always scan if it's the first time or if we need to ensure placeholders are replaced.
00713         // We removed the optimization because it prevents newly added modules from being initialized
00714         // with the correct paths if the main project path remains the same.
00715         /*
00716         if ($lastPath === $currentPath && !empty($lastPath)) {
00717             Log::debug('Path unchanged, skipping file scan (performance optimization)');
00718             Log::trace('Last path: "' . $lastPath . '" matches current path: "' . $currentPath . '"');
00719             
00720             $this->filesToScan = [];
00721             $this->writeLog('Files to scan: 0 (path unchanged - scan skipped)');
00722             return;
00723         }
00724         */
00725 
00726         // Path changed or first run, perform full scan
00727         if ($lastPath !== $currentPath || empty($lastPath)) {
00728             Log::debug('Path changed or first run, performing full file scan');
00729             Log::trace('Last path: "' . $lastPath . '" differs from current path: "' . $currentPath . '"');
00730             $this->writeLog('Path changed detected - performing full scan');
00731         } else {
00732             Log::debug('Ensuring configuration files are checked for placeholders');
00733             $this->writeLog('Scanning configuration files for placeholders');
00734         }
00735 
00736         $scanStartTime = Util::getMicrotime();
00737         $this->filesToScan = Util::getFilesToScan();
00738         $scanDuration = round(Util::getMicrotime() - $scanStartTime, 3);
00739 
00740         $this->writeLog('Files to scan: ' . count($this->filesToScan) . ' (scanned in ' . $scanDuration . 's)');
00741     }
