00894     private function createSslCrts()
00895     {
00896         global $bearsamppLang, $bearsamppOpenSsl, $bearsamppBins;
00897 
00898         Log::info('Checking SSL certificates during startup...');
00899         $this->splash->incrProgressBar();
00900 
00901         // Always ensure localhost exists and is valid
00902         $localhostExpired = $bearsamppOpenSsl->isExpired('localhost');
00903         Log::trace('Localhost SSL expired status: ' . ($localhostExpired ? 'YES' : 'NO'));
00904 
00905         if ($localhostExpired) {
00906             Log::info('SSL certificate for "localhost" is missing or expired. Checking if creation is necessary...');
00907             $this->splash->setTextLoading(sprintf($bearsamppLang->getValue(Lang::STARTUP_GEN_SSL_CRT_TEXT), 'localhost'));
00908             
00909             // Only create if NOT present or REALLY expired
00910             // (isExpired already returns true if missing)
00911             if (!$bearsamppOpenSsl->createCrt('localhost')) {
00912                 Log::error('FAILED call to createCrt("localhost")');
00913             }
00914             
00915             // Re-verify after creation to log success/failure
00916             if ($bearsamppOpenSsl->isExpired('localhost')) {
00917                 Log::error('FAILED to verify localhost SSL certificate after creation attempt.');
00918             } else {
00919                 Log::info('Successfully verified localhost SSL certificate.');
00920             }
00921         } else {
00922             Log::trace('SSL certificate for "localhost" is valid.');
00923         }
00924 
00925         // Also check all Apache vhosts
00926         $apache = $bearsamppBins->getApache();
00927         if ($apache) {
00928             $vhosts = $apache->getVhosts();
00929             Log::info('Checking SSL certificates for ' . count($vhosts) . ' vhosts');
00930             foreach ($vhosts as $vhost) {
00931                 if ($bearsamppOpenSsl->isExpired($vhost)) {
00932                     Log::info('SSL certificate for "' . $vhost . '" is missing or expired. Creating new one...');
00933                     $this->splash->setTextLoading(sprintf($bearsamppLang->getValue(Lang::STARTUP_GEN_SSL_CRT_TEXT), $vhost));
00934                     if (!$bearsamppOpenSsl->createCrt($vhost)) {
00935                         Log::error('FAILED call to createCrt("' . $vhost . '")');
00936                     }
00937                 } else {
00938                     Log::trace('SSL certificate for "' . $vhost . '" is valid.');
00939                 }
00940             }
00941         } else {
00942             Log::info('Apache module not found or disabled, skipping vhost SSL check');
00943         }
00944     }
