00954     private function installServices()
00955     {
00956         global $bearsamppLang, $bearsamppBins, $bearsamppRoot;
00957 
00958         Log::trace('Starting installServices method');
00959 
00960         if (!$this->restart) {
00961             Log::trace('Normal startup mode - processing services');
00962 
00963             // Admin check is now performed at the very beginning of processWindow()
00964             // No need to check again here
00965 
00966             // Service Installation
00967             $this->installServicesSequential($bearsamppBins, $bearsamppLang);
00968         } else {
00969             Log::trace('Restart mode - skipping service installation');
00970             $this->splash->incrProgressBar(self::GAUGE_SERVICES * count($bearsamppBins->getServices()));
00971         }
00972 
00973         Log::trace('Completed installServices method');
00974     }
00975 
00984     private function installServicesSequential($bearsamppBins, $bearsamppLang)
00985     {
00986         Log::trace('Starting sequential service installation');
00987         $installStartTime = Util::getMicrotime();
00988 
00989         // Pre-fetch all services to speed up preparation phase
00990         Win32Service::getServices(true);
00991 
00992         // Skip symlink creation during checking phase for performance
00993         Symlinks::setSkipSymlinkCreation(true);
00994 
00995         try {
00996             // Step 1: Check and prepare all services
00997             $servicesToStart = [];
00998             $serviceErrors = [];
00999 
01000             $totalServiceCount = count($bearsamppBins->getServices());
01001             $currentServiceIndex = 0;
01002 
01003             foreach ($bearsamppBins->getServices() as $sName => $service) {
01004                 $currentServiceIndex++;
01005 
01006                 Log::trace('Preparing service: ' . $sName);
01007 
01008                 // prepareService() increments 1 step
01009                 $serviceInfo = $this->prepareService($sName, $service, $bearsamppBins, $bearsamppLang, $currentServiceIndex, $totalServiceCount);
01010 
01011                 if ($serviceInfo['restart']) {
01012                     $this->writeLog('Need restart: installService ' . $serviceInfo['bin']->getName());
01013                     Log::trace('Restart required for service: ' . $serviceInfo['bin']->getName());
01014                     $this->restart = true;
01015                     // prepareService used 1 step, need 4 more to reach GAUGE_SERVICES (5 total)
01016                     $this->splash->incrProgressBar(self::GAUGE_SERVICES - 1);
01017                     continue;
01018                 }
01019 
01020                 if (!empty($serviceInfo['error'])) {
01021                     $serviceErrors[$sName] = $serviceInfo;
01022                     // prepareService used 1 step, need 4 more to reach GAUGE_SERVICES (5 total)
01023                     $this->splash->incrProgressBar(self::GAUGE_SERVICES - 1);
01024                     continue;
01025                 }
01026 
01027                 if ($serviceInfo['needsStart']) {
01028                     $servicesToStart[$sName] = $serviceInfo;
01029                 } else {
01030                     // Service already running or doesn't need to start
01031                     // prepareService used 1 step, need 4 more to reach GAUGE_SERVICES (5 total)
01032                     $this->splash->incrProgressBar(self::GAUGE_SERVICES - 1);
01033                 }
01034             }
01035         } finally {
01036             // Re-enable symlink creation and reload bins with symlinks created
01037             Symlinks::setSkipSymlinkCreation(false);
01038             Log::trace('Re-enabling symlink creation after service checking');
01039             $bearsamppBins->reload();
01040         }
01041 
01042         // Step 2: Start all services in parallel with progress updates
01043         if (!empty($servicesToStart)) {
01044             Log::trace('Starting ' . count($servicesToStart) . ' services in parallel');
01045 
01046             $parallelStartTime = Util::getMicrotime();
01047             $serviceCount = 0;
01048             $totalServices = count($servicesToStart);
01049 
01050             // Use parallel startup for optimized performance (40-60% faster)
01051             ServiceHelper::startAllServicesParallel(
01052                 $servicesToStart,
01053                 function($current, $total, $serviceName) use (&$serviceCount, $bearsamppLang) {
01054                     $this->splash->setTextLoading(sprintf($bearsamppLang->getValue(Lang::LOADING_START_SERVICE), $serviceName) . ' (' . $current . '/' . $total . ')');
01055                     // Increment progress bar as each start command is sent
01056                     if ($current > $serviceCount) {
01057                         $this->splash->incrProgressBar();
01058                         $serviceCount = $current;
01059                     }
01060                 }
01061             );
01062 
01063             // Check which services are actually running and handle failures
01064             $parallelDuration = round(Util::getMicrotime() - $parallelStartTime, 3);
01065             Log::trace('Parallel startup phase completed in ' . $parallelDuration . ' seconds');
01066 
01067             $verifyCount = 0;
01068             foreach ($servicesToStart as $sName => $serviceInfo) {
01069                 $verifyCount++;
01070                 $name = $serviceInfo['name'];
01071                 $service = $serviceInfo['service'];
01072 
01073                 // Update splash during verification phase
01074                 $this->splash->setTextLoading(sprintf($bearsamppLang->getValue(Lang::STARTUP_VERIFY_SERVICE_TEXT), $name) . ' (' . $verifyCount . '/' . $totalServices . ')');
01075 
01076                 if ($service->isRunning()) {
01077                     $this->writeLog($name . ' service started successfully');
01078                     Log::trace('Service ' . $name . ' verified running');
01079                 } else {
01080                     $error = $service->getError();
01081                     if (empty($error)) {
01082                         $error = 'Failed to start service after parallel startup';
01083                     }
01084 
01085                     $serviceErrors[$sName] = $serviceInfo;
01086                     $serviceErrors[$sName]['error'] = $error;
01087                     Log::warning('Service ' . $name . ' failed to start: ' . $error);
01088 
01089                     // Run syntax check if available
01090                     if (!empty($serviceInfo['syntaxCheckCmd'])) {
01091                         try {
01092                             $cmdSyntaxCheck = $serviceInfo['bin']->getCmdLineOutput($serviceInfo['syntaxCheckCmd']);
01093                             if (!$cmdSyntaxCheck['syntaxOk']) {
01094                                 $serviceErrors[$sName]['error'] .= PHP_EOL . 'Syntax error: ' . $cmdSyntaxCheck['content'];
01095                             }
01096                         } catch (\Exception $e) {
01097                             // Ignore syntax check errors
01098                         }
01099                     }
01100                 }
01101 
01102                 // Increment progress bar for verification step
01103                 // Total for parallel path: 1 (prepare) + 1 (start callback) + 3 (verify) = 5
01104                 $this->splash->incrProgressBar(self::GAUGE_SERVICES - 2);
01105             }
01106 
01107             Log::info('Parallel service startup completed: ' . count($servicesToStart) . ' services processed');
01108         }
01109 
01110         // Step 3: Report any errors
01111         foreach ($serviceErrors as $sName => $serviceInfo) {
01112             if (!empty($serviceInfo['error'])) {
01113                 Log::trace('Service error occurred for ' . $sName . ': ' . $serviceInfo['error']);
01114                 if (!empty($this->error)) {
01115                     $this->error .= PHP_EOL . PHP_EOL;
01116                 }
01117                 $this->error .= sprintf($bearsamppLang->getValue(Lang::STARTUP_SERVICE_ERROR), $serviceInfo['name']) . PHP_EOL . $serviceInfo['error'];
01118             }
01119         }
01120 
01121         $installDuration = round(Util::getMicrotime() - $installStartTime, 3);
01122         $this->writeLog('Service installation completed in ' . $installDuration . 's');
01123         Log::trace('Service installation completed in ' . $installDuration . ' seconds');
01124     }
01125 
01137     private function prepareService($sName, $service, $bearsamppBins, $bearsamppLang, $currentIndex = 0, $totalCount = 0)
01138     {
01139         $serviceInfo = [
01140             'sName' => $sName,
01141             'service' => $service,
01142             'bin' => null,
01143             'name' => '',
01144             'port' => 0,
01145             'syntaxCheckCmd' => null,
01146             'error' => '',
01147             'restart' => false,
01148             'needsStart' => false,
01149             'startTime' => Util::getMicrotime()
01150         ];
01151 
01152         // Identify service type and get bin
01153         $syntaxCheckCmd = null;
01154         $bin = null;
01155         $port = 0;
01156 
01157         if ($sName == BinMailpit::SERVICE_NAME) {
01158             $bin = $bearsamppBins->getMailpit();
01159             $port = $bearsamppBins->getMailpit()->getSmtpPort();
01160         } elseif ($sName == BinMemcached::SERVICE_NAME) {
01161             $bin = $bearsamppBins->getMemcached();
01162             $port = $bearsamppBins->getMemcached()->getPort();
01163         } elseif ($sName == BinApache::SERVICE_NAME) {
01164             $bin = $bearsamppBins->getApache();
01165             $port = $bearsamppBins->getApache()->getPort();
01166             $syntaxCheckCmd = BinApache::CMD_SYNTAX_CHECK;
01167         } elseif ($sName == BinMysql::SERVICE_NAME) {
01168             $bin = $bearsamppBins->getMysql();
01169             $port = $bearsamppBins->getMysql()->getPort();
01170             $syntaxCheckCmd = BinMysql::CMD_SYNTAX_CHECK;
01171 
01172             // Pre-initialize MySQL data if needed
01173             if (!file_exists($bin->getDataDir()) || count(glob($bin->getDataDir() . '/*')) === 0) {
01174                 Log::trace('Pre-initializing MySQL data directory');
01175                 $bin->initData();
01176             }
01177         } elseif ($sName == BinMariadb::SERVICE_NAME) {
01178             $bin = $bearsamppBins->getMariadb();
01179             $port = $bearsamppBins->getMariadb()->getPort();
01180             $syntaxCheckCmd = BinMariadb::CMD_SYNTAX_CHECK;
01181         } elseif ($sName == BinPostgresql::SERVICE_NAME) {
01182             $bin = $bearsamppBins->getPostgresql();
01183             $port = $bearsamppBins->getPostgresql()->getPort();
01184         } elseif ($sName == BinXlight::SERVICE_NAME) {
01185             $bin = $bearsamppBins->getXlight();
01186             $port = $bearsamppBins->getXlight()->getPort();
01187         }
01188 
01189         $name = $bin->getName() . ' ' . $bin->getVersion() . ' (' . $service->getName() . ')';
01190 
01191         $serviceInfo['bin'] = $bin;
01192         $serviceInfo['name'] = $name;
01193         $serviceInfo['port'] = $port;
01194         $serviceInfo['syntaxCheckCmd'] = $syntaxCheckCmd;
01195 
01196         // Update splash with current service being checked (1 step)
01197         if ($currentIndex > 0 && $totalCount > 0) {
01198             $this->splash->setTextLoading('Checking ' . $bin->getName() . ' service (' . $currentIndex . '/' . $totalCount . ')');
01199         }
01200         $this->splash->incrProgressBar();
01201 
01202         // Check if service is already installed
01203         $serviceAlreadyInstalled = false;
01204         $serviceToRemove = false;
01205 
01206         // Skip service checks for disabled services
01207         if (!$bin->isEnable()) {
01208             Log::trace('Skipping service check for disabled bin: ' . $bin->getName());
01209             $serviceInfos = false;
01210         } else if ($sName == BinApache::SERVICE_NAME) {
01211             $serviceInfos = $this->checkApacheServiceWithTimeout($service);
01212         } else if ($sName == BinMysql::SERVICE_NAME) {
01213             $serviceInfos = $this->checkMySQLServiceWithTimeout($service, $bin);
01214             if ($serviceInfos === false && $service->isInstalled()) {
01215                 Log::trace('MySQL service appears to be hanging, forcing restart');
01216                 Win32Ps::killBins(['mysqld.exe']);
01217                 $service->delete();
01218                 $serviceToRemove = true;
01219             }
01220         } else {
01221             try {
01222                 $serviceInfos = $service->infos();
01223             } catch (\Exception $e) {
01224                 Log::trace("Exception during service check: " . $e->getMessage());
01225                 $serviceInfos = false;
01226             } catch (\Throwable $e) {
01227                 Log::trace("Throwable during service check: " . $e->getMessage());
01228                 $serviceInfos = false;
01229             }
01230         }
01231 
01232         if ($serviceInfos !== false) {
01233             $serviceAlreadyInstalled = true;
01234             $this->writeLog($name . ' service already installed');
01235 
01236             // Check if service needs to be removed and reinstalled
01237             if ($sName == BinPostgresql::SERVICE_NAME) {
01238                 $serviceGenPathName = trim(str_replace('"', '', $service->getBinPath()));
01239                 $installedPathParts = explode(' ', $serviceInfos[Win32Service::VBS_PATH_NAME], 2);
01240                 $serviceVbsPathName = trim(str_replace('"', '', $installedPathParts[0]));
01241             } else {
01242                 $serviceGenPathName = trim(str_replace('"', '', $service->getBinPath() . ($service->getParams() ? ' ' . $service->getParams() : '')));
01243                 $serviceVbsPathName = trim(str_replace('"', '', $serviceInfos[Win32Service::VBS_PATH_NAME]));
01244             }
01245 
01246             $normalizedGenPath = preg_replace('/\s+/', ' ', $serviceGenPathName);
01247             $normalizedVbsPath = preg_replace('/\s+/', ' ', $serviceVbsPathName);
01248 
01249             if ($normalizedGenPath !== $normalizedVbsPath && $serviceGenPathName != $serviceVbsPathName) {
01250                 $serviceToRemove = true;
01251                 $this->writeLog($name . ' service has to be removed');
01252             }
01253         }
01254 
01255         // Remove service if needed (no progress increment - part of check phase)
01256         if ($serviceToRemove) {
01257             if (!$service->delete()) {
01258                 $serviceInfo['restart'] = true;
01259                 return $serviceInfo;
01260             }
01261         }
01262 
01263         // Check port availability (no progress increment - part of check phase)
01264         $isPortInUse = Util::isPortInUse($port);
01265         if ($isPortInUse !== false) {
01266             // Port is in use - check if it's our service that's already running
01267             $isRunning = false;
01268             if ($serviceInfos !== false && is_array($serviceInfos)) {
01269                 // Extract state from serviceInfos array (works for both NSSM and Win32Service)
01270                 $state = $serviceInfos[Win32Service::SERVICE_STATE] ?? $serviceInfos['CurrentState'] ?? null;
01271 
01272                 // Check if running: state can be numeric '4' or string 'RUNNING'
01273                 if ($state !== null) {
01274                     $isRunning = ($state == Win32Service::WIN32_SERVICE_RUNNING) ||
01275                                  (strtoupper((string)$state) === 'RUNNING');
01276                 } else {
01277                     // Fallback to calling isRunning() if state is not found
01278                     $isRunning = $service->isRunning();
01279                 }
01280             } else if ($serviceInfos === false) {
01281                 // Fallback when serviceInfos is false
01282                 $isRunning = $service->isRunning();
01283             }
01284 
01285             if ($isRunning) {
01286                 // Service is already running and owns the port - this is OK
01287                 $this->writeLog($name . ' service already running on port ' . $port);
01288                 Log::trace('Service ' . $name . ' already running - no need to start');
01289                 $serviceInfo['needsStart'] = false;
01290                 return $serviceInfo;
01291             }
01292 
01293             // Fallback to a single status check if serviceInfos didn't give us the answer
01294             if ($serviceInfos === false && $service->isRunning()) {
01295                 $this->writeLog($name . ' service already running on port ' . $port);
01296                 Log::trace('Service ' . $name . ' already running - no need to start');
01297                 $serviceInfo['needsStart'] = false;
01298                 return $serviceInfo;
01299             }
01300 
01301             // Port is in use by something else - this is an error
01302             $serviceInfo['error'] = sprintf($bearsamppLang->getValue(Lang::STARTUP_SERVICE_PORT_ERROR), $port, $isPortInUse);
01303             return $serviceInfo;
01304         }
01305 
01306         // Install service if needed (no progress increment - part of check phase)
01307         if (!$serviceAlreadyInstalled || $serviceToRemove) {
01308             if (!$service->create()) {
01309                 $serviceInfo['error'] = sprintf($bearsamppLang->getValue(Lang::STARTUP_SERVICE_CREATE_ERROR), $service->getError());
01310                 return $serviceInfo;
01311             }
01312         }
01313 
01314         $serviceInfo['needsStart'] = true;
01315         return $serviceInfo;
01316     }
