01342     private function checkApacheServiceWithTimeout($service)
01343     {
01344         Log::trace('Starting specialized Apache service check with timeout protection');
01345 
01346         // Set a timeout for the Apache service check
01347         $serviceCheckStartTime = microtime(true);
01348         $serviceCheckTimeout = 3; // 3 seconds timeout
01349 
01350         try {
01351             // Use a non-blocking approach to check service
01352             $serviceInfos = false;
01353 
01354             // First try a quick check if the service exists in the list
01355             $serviceList = Win32Service::getServices();
01356             if (is_array($serviceList) && isset($serviceList[$service->getName()])) {
01357                 Log::trace('Apache service found in service list, getting details');
01358 
01359                 // Service exists, now try to get its details with timeout protection
01360                 $startTime = microtime(true);
01361                 $serviceInfos = $service->infos();
01362 
01363                 // Check if we've exceeded our timeout
01364                 if (microtime(true) - $serviceCheckStartTime > $serviceCheckTimeout) {
01365                     Log::trace("Apache service check timeout exceeded, assuming service needs reinstall");
01366                     return false;
01367                 }
01368             } else {
01369                 Log::trace('Apache service not found in service list');
01370                 return false;
01371             }
01372 
01373             return $serviceInfos;
01374         } catch (\Exception $e) {
01375             Log::trace("Exception during Apache service check: " . $e->getMessage());
01376             return false;
01377         } catch (\Throwable $e) {
01378             Log::trace("Throwable during Apache service check: " . $e->getMessage());
01379             return false;
01380         }
01381     }
